class AddNotesDialogController{constructor($mdDialog,toastrService,DispatchData,id,fieldName,title,job){this._$mdDialog=$mdDialog;this._dispatchData=DispatchData;this._toastrService=toastrService;this.isLoading=false;this.id=id;this.title=title;this._job=job;this._fieldName=fieldName;this.note=""}async submit(note){try{this.isLoading=true;if(this._fieldName==="Notes"){await this.addJobNote(this._job.id,note,FirstName,this._job.preBook,this._job.bulkJob)}else{const callData={call:"updateDetailField",field:this._fieldName,value:note,jobID:this._job.id};await this.updateJobDetail(this._job.bulkJob,callData.jobID,callData.field,callData.value,this._job.charge,FirstName,ContactID,this._job.preBook)}this._toastrService.showSuccessToast("Added Note To Job");this._$mdDialog.hide()}catch(error){this._toastrService.showErrorToast(error.message)}finally{this.isLoading=false}}async addJobNote(id,note,firstName,preBook,bulkJob){if(bulkJob){await this._dispatchData.addBulkJobNote(id,note,firstName,preBook)}else{await this._dispatchData.addNote(id,note,firstName,preBook)}}async updateJobDetail(bulkJob,jobID,field,value,charge,firstName,contactID,preBook){if(bulkJob){await this._dispatchData.updateBulkJobDetail(jobID,field,value,charge,firstName,contactID)}else{await this._dispatchData.updateJobDetail(jobID,field,value,charge,firstName,contactID,preBook)}}cancel(){this._$mdDialog.cancel()}}